// ============================================================
// SOCIAL ADS — Fan out: 1 item per (ad spec × variation index)
// ============================================================
// Trusts user_id (JWT-verified server-side) but NOTHING else.
// Builds a prompt that asks gpt-image-1 to leave text zones
// EMPTY — the composer route overlays the real text downstream.
//
// Picks the FAL endpoint based on whether reference images are
// provided:
//   • Has hero / extras → fal-ai/gpt-image-1/edit-image/byok
//   • Otherwise         → fal-ai/gpt-image-1/text-to-image/byok
// ============================================================

const body = $json.body || $json;

if (!body.user_id) throw new Error('Missing user_id — call via /api/social-ads/generate.');
if (!Array.isArray(body.items) || body.items.length === 0) {
  throw new Error('Missing items[].');
}

const PLATFORM_SIZES = {
  'instagram-post':     { w: 1080, h: 1080, aspect: '1:1 square',         fal_size: '1024x1024' },
  'instagram-story':    { w: 1080, h: 1920, aspect: '9:16 vertical',      fal_size: '1024x1536' },
  'facebook-post':      { w: 1200, h: 630,  aspect: '1.91:1 landscape',   fal_size: '1536x1024' },
  'linkedin-post':      { w: 1200, h: 627,  aspect: '1.91:1 landscape',   fal_size: '1536x1024' },
  'youtube-thumbnail':  { w: 1280, h: 720,  aspect: '16:9 landscape',     fal_size: '1536x1024' },
  'whatsapp-status':    { w: 1080, h: 1920, aspect: '9:16 vertical',      fal_size: '1024x1536' },
  'newspaper-ad':       { w: 1500, h: 1100, aspect: '1.36:1 landscape',   fal_size: '1536x1024' }
};

const CATEGORY_GUIDE = {
  'doctor':               'Professional medical visual. Blue and white palette. Doctor portrait (white coat + stethoscope) on the right third. Service icons row (checkup, appointment, medicine). Calm clinical background blur. Trust-building, hygienic.',
  'hospital-clinic':      'Modern hospital visual. Clean blue/teal palette. Building hero or interior reception. Reassuring professional feel.',
  'restaurant-food':      'Appetizing food visual. Warm orange/red palette. Top-down hero food shot or plated dish photo. Mouth-watering, vibrant.',
  'real-estate':          'Modern real estate visual. Premium grey/blue palette. House or building hero on a serving tray or skyline. Clean aspirational.',
  'gift-shop':            'Festive colorful gift shop visual. Confetti, gift box illustrations, festival theme. Bright cheerful palette.',
  'hotel':                'Luxury hotel visual. Dark warm brown/gold background. Three-photo collage center (room, pool, dining). Premium resort feel.',
  'jewellery':            'Premium jewellery visual. Dark velvet or jewel-tone background. Subtle sparkle. Product hero center. Luxury showroom.',
  'fashion-boutique':     'Editorial magazine layout. Model in outfit (if hero provided). Seasonal collection feel.',
  'industrial-steel':     'Bold industrial visual. Multi-panel grid layout. Infrastructure imagery (bridges, buildings, elephant for strength). Earth tones with red/yellow accents.',
  'education-coaching':   'Bright optimistic coaching visual. Blue + yellow palette. Student photo or success symbol. Trust-building.',
  'salon-spa':            'Soft pastel pink/peach salon visual. Elegant. Model with styled hair or spa setup. Calming luxe feel.',
  'automobile-servicing': 'Bold dark blue or black garage background with red/yellow accents. Car or bike hero on a lift or in service bay (use hero image if provided). Industrial mechanic-trust feel. Tools or service-bay details in soft focus.',
  'gym-fitness':          'High-energy dark gym background. Athlete or equipment hero. Bold red/orange accents.',
  'wedding-planner':      'Elegant rose-gold / blush palette. Couple silhouette or floral mandap. Romantic.',
  'travel-tours':         'Vibrant destination hero (beach, mountain, monument). Sky-blue + sunshine palette.',
  'pooja-store':          'Warm orange / saffron palette. Diya, brass items, marigold. Devotional traditional.',
  'general-business':     'Modern business visual. Clean professional layout. Brand-color accent. Hero product/service photo.'
};

const STYLE_GUIDE = {
  'modern':           'modern flat design, generous whitespace, subtle gradients',
  'luxury':           'dark premium palette, gold accents, soft glow lighting',
  'festive':          'bright celebratory colors, confetti / floral motifs, joyful',
  'minimal':          'monochrome or two-tone palette, lots of whitespace, restrained',
  'bold-industrial':  'high-contrast bold palette, strong red / yellow / black, gritty texture',
  'traditional':      'ethnic ornamental motifs, warm spice palette, classical'
};

function buildPrompt(spec, varIdx) {
  const size = PLATFORM_SIZES[spec.platform];
  const catDesc = CATEGORY_GUIDE[spec.business_category] || CATEGORY_GUIDE['general-business'];
  const styleDesc = STYLE_GUIDE[spec.style_theme] || STYLE_GUIDE['modern'];
  const hasHero = Boolean(spec.hero_image_url);

  return `
ROLE: Senior social-media ad designer.
GOAL: Create ONE ${size.aspect} background composition (${size.w}x${size.h}) for the ${spec.platform} platform. Variation ${varIdx + 1} of ${spec.variations}.

========================================================
  CATEGORY DIRECTION
========================================================
${catDesc}

========================================================
  STYLE
========================================================
${styleDesc}
${spec.color_palette ? `Honor brand colors: ${spec.color_palette}` : ''}

========================================================
  CRITICAL — TEXT ZONES MUST BE EMPTY
========================================================
DO NOT render any text, headlines, taglines, prices, phone numbers, business names, lorem ipsum, or watermarks anywhere on the image.
Reserve these zones EMPTY / blurred / neutral so that text overlays can be composited later:
  • Top-left corner (18% width × 14% height) — clean, calm — LOGO will go here
  • Top-right corner (18% × 18%) — clean, calm — OFFER BADGE will go here
  • Bottom 10% strip — clean, gently darker — CONTACT info will go here
  • Center 60% width — leave a clean band where the headline will be overlaid

========================================================
  HERO REFERENCE
========================================================
${hasHero ? '- A hero image is provided as a reference. Use it as the primary visual subject (product / person / building). Preserve brand-critical features faithfully.' : '- No hero provided — synthesize a category-appropriate professional photo.'}

========================================================
  RULES
========================================================
1. Single photograph composition — NO collages / split frames.
2. NO TEXT of any kind. NO labels, NO prices, NO URLs, NO Lorem Ipsum.
3. NO logos baked in.
4. Photo-realistic where appropriate (real estate, food, automobile); editorial where appropriate (fashion, jewellery).

${spec.custom_instruction ? `EXTRA INSTRUCTION: "${spec.custom_instruction}"` : ''}

Return one image at ${size.fal_size}.
`.trim();
}

const out = [];
for (const item of body.items) {
  const size = PLATFORM_SIZES[item.platform] || PLATFORM_SIZES['instagram-post'];
  const variations = Math.max(1, Math.min(4, Number(item.variations) || 1));

  // Reference images for the edit-image endpoint.
  const refs = [
    item.hero_image_url,
    ...(Array.isArray(item.extra_image_urls) ? item.extra_image_urls : [])
  ].filter(Boolean);
  const hasRefs = refs.length > 0;
  // FAL endpoint pick:
  //   With refs → edit-image (keeps hero faithful)
  //   Without   → text-to-image
  const falEndpoint = hasRefs
    ? 'https://fal.run/fal-ai/gpt-image-1/edit-image/byok'
    : 'https://fal.run/fal-ai/gpt-image-1/text-to-image/byok';

  for (let v = 0; v < variations; v++) {
    out.push({
      json: {
        user_id: body.user_id,
        batch_id: body.batch_id || null,
        generation_id: item.generation_id,
        variation_index: v,
        total_variations: variations,
        platform: item.platform,
        fal_size: size.fal_size,
        fal_endpoint: falEndpoint,
        has_refs: hasRefs,
        reference_urls: refs,
        final_w: size.w,
        final_h: size.h,
        language: item.language,
        category: item.business_category,
        // pass through every text + url field for the composite stage
        business_name: item.business_name,
        main_headline: item.main_headline,
        tagline: item.tagline,
        offer_text: item.offer_text,
        contact_info: item.contact_info,
        logo_url: item.logo_url,
        hero_image_url: item.hero_image_url,
        extra_image_urls: item.extra_image_urls || [],
        master_prompt: buildPrompt(item, v)
      }
    });
  }
}

if (!out.length) throw new Error('Fan-out produced 0 items.');
return out;

// ============================================================
// FAL gpt-image-1 returns:
//   { images: [{ url, content_type, width, height }], ... }
// We pass the URL straight to the composite route — no temp
// upload needed, FAL URLs are publicly fetchable for ~24h.
// ============================================================

const resp = $json;
const meta = $('Fan out: spec × variations').itemMatching($itemIndex)?.json
          || $('Fan out: spec × variations').item.json;

// HTTP node error path (continueOnFail) may surface as { error } / { detail }
if (resp?.error || resp?.detail) {
  return [{
    json: {
      ...meta,
      ok: false,
      error_message: 'FAL error: ' + JSON.stringify(resp.error || resp.detail).slice(0, 400)
    }
  }];
}

const images = resp?.images || resp?.data?.images || [];
const first = images[0];
if (!first?.url) {
  return [{
    json: {
      ...meta,
      ok: false,
      error_message: 'FAL returned no image. Raw: ' + JSON.stringify(resp).slice(0, 400)
    }
  }];
}

return [{
  json: {
    ...meta,
    ok: true,
    base_image_url: first.url,
    fal_seed: resp.seed || null
  }
}];

// Collect the composite route's output_url, prepare to aggregate.
const resp = $json;
const meta = $('Extract FAL Result').item.json;
if (!resp?.success || !resp?.output_url) {
  return [{ json: { ...meta, ok: false, error_message: resp?.error || 'composite failed' } }];
}
return [{
  json: {
    user_id: meta.user_id,
    batch_id: meta.batch_id,
    generation_id: meta.generation_id,
    variation_index: meta.variation_index,
    total_variations: meta.total_variations,
    platform: meta.platform,
    output_url: resp.output_url,
    ok: true
  }
}];

// ============================================================
// Aggregate: group all variation outputs by generation_id and
// emit one PATCH per generation row.
// ============================================================
const items = $input.all().map((i) => i.json).filter((j) => j.ok);
const byGen = new Map();
for (const it of items) {
  const arr = byGen.get(it.generation_id) || [];
  arr.push(it);
  byGen.set(it.generation_id, arr);
}
const out = [];
for (const [gid, arr] of byGen) {
  arr.sort((a, b) => a.variation_index - b.variation_index);
  out.push({
    json: {
      generation_id: gid,
      batch_id: arr[0]?.batch_id || null,
      user_id: arr[0]?.user_id,
      output_urls: arr.map((a) => a.output_url),
      output_url: arr[0]?.output_url || null,
      total_variations: arr[0]?.total_variations || arr.length
    }
  });
}
return out;

// Build one final aggregate payload for the response.
const items = $input.all().map((i) => i.json);
return [{
  json: {
    success: true,
    generation_ids: items.map((i) => i.generation_id),
    batch_id: items[0]?.batch_id || null,
    outputs: items.map((i) => ({
      generation_id: i.generation_id,
      output_urls: i.output_urls
    }))
  }
}];
